INSERT INTO med_visites(id,mat,type,prevue_le,realisee_le,statut,aptitude,prochaine_le,maj,par)
INSERT INTO frm_catalogue(id,code,titre,type,duree_h,validite_mois,actif,cree) SELECT 'fc'||g, 'F'||g, 'Formation '||g, (ARRAY['interne','externe','habilitation'])[1+g%3], 7 + g % 30, CASE WHEN g%3=2 THEN 24 END, 1, now()::text FROM generate_series(1,200) g ON CONFLICT DO NOTHING;
INSERT INTO frm_sessions(id,catalogue_id,debut,fin,lieu,places,statut,cree) SELECT 'fs'||g, 'fc'||(1+g%200), to_char(date '2024-01-01' + (g % 1000), 'YYYY-MM-DD'), to_char(date '2024-01-02' + (g % 1000), 'YYYY-MM-DD'), 'Salle '||(g%20), 20, (ARRAY['planifiee','realisee','cloturee'])[1+g%3], now()::text FROM generate_series(1,3000) g ON CONFLICT DO NOTHING;
INSERT INTO frm_inscriptions(id,session_id,mat,presence,resultat,maj) SELECT 'fi'||g, 'fs'||(1+g%3000), (100001 + (g*7) % 50000)::text, (ARRAY['present','absent','inscrit'])[1+g%3], CASE WHEN g%3=0 THEN 'reussi' END, now()::text FROM generate_series(1,150000) g ON CONFLICT DO NOTHING;
INSERT INTO frm_habilitations(id,mat,catalogue_id,obtenue_le,expire_le,maj) SELECT 'fh'||g, (100001 + g % 50000)::text, 'fc'||(3*(1+g%66)), to_char(date '2023-01-01' + (g % 900), 'YYYY-MM-DD'), to_char(date '2025-06-01' + (g % 900), 'YYYY-MM-DD'), now()::text FROM generate_series(1,100000) g ON CONFLICT DO NOTHING;
INSERT INTO frm_besoins(id,mat,catalogue_id,origine,statut,cree) SELECT 'fb'||g, (100001 + g % 50000)::text, 'fc'||(1+g%200), (ARRAY['manuel','ecart','expiration'])[1+g%3], (ARRAY['ouvert','planifie','satisfait'])[1+g%3], now()::text FROM generate_series(1,50000) g ON CONFLICT DO NOTHING;
INSERT INTO comp_catalogue(id,code,nom,domaine,actif,cree) SELECT 'cc'||g, 'C'||g, 'Compétence '||g, 'Domaine '||(g%8), 1, now()::text FROM generate_series(1,100) g ON CONFLICT DO NOTHING;
INSERT INTO comp_exigences(fonction,competence_id,niveau) SELECT f, 'cc'||(1+(g*3)%100), 1+g%4 FROM unnest(ARRAY['Ouvrier','Technicien','Cadre','Agent']) f, generate_series(1,20) g ON CONFLICT DO NOTHING;
INSERT INTO comp_niveaux(mat,competence_id,niveau,d,evaluateur) SELECT (100001 + g % 50000)::text, 'cc'||(1+(g/50000 + g)%100), 1+g%4, '2026-01-15', 'banc' FROM generate_series(0,499999) g ON CONFLICT DO NOTHING;
INSERT INTO comp_historique(id,mat,competence_id,avant,apres,par,ts) SELECT 'ch'||g, (100001 + g % 50000)::text, 'cc'||(1+g%100), g%4, 1+g%4, 'banc', now()::text FROM generate_series(1,500000) g ON CONFLICT DO NOTHING;
INSERT INTO hse_evenements(id,type,d,site_id,mat,gravite,arret,jours_arret,description,statut,cree) SELECT 'he'||g, (ARRAY['accident','presqu_accident','incident','maladie'])[1+g%4], to_char(date '2023-01-01' + (g % 1380), 'YYYY-MM-DD'), 'bs'||(1+g%20), (100001 + g % 50000)::text, 1+g%4, CASE WHEN g%5=0 THEN 1 ELSE 0 END, CASE WHEN g%5=0 THEN g%30 ELSE 0 END, 'Événement '||g, (ARRAY['ouvert','analyse','clos'])[1+g%3], now()::text FROM generate_series(1,20000) g ON CONFLICT DO NOTHING;
INSERT INTO hse_actions(id,evenement_id,titre,responsable,echeance,statut,cree) SELECT 'ha'||g, 'he'||(1+g%20000), 'Action '||g, (100001 + g % 50000)::text, to_char(date '2025-01-01' + (g % 700), 'YYYY-MM-DD'), (ARRAY['ouverte','faite'])[1+g%2], now()::text FROM generate_series(1,10000) g ON CONFLICT DO NOTHING;
INSERT INTO hse_epi(id,mat,type,remis_le,renouveler_le) SELECT 'hp'||g, (100001 + g % 50000)::text, (ARRAY['casque','chaussures','gants'])[1+g%3], to_char(date '2024-01-01' + (g % 600), 'YYYY-MM-DD'), to_char(date '2025-06-01' + (g % 600), 'YYYY-MM-DD') FROM generate_series(1,150000) g ON CONFLICT DO NOTHING;
INSERT INTO rec_postes(id,intitule,fonction,site_id,nb,statut,ouvert_le) SELECT 'rp'||g, 'Poste '||g, (ARRAY['Ouvrier','Technicien','Cadre','Agent'])[1+g%4], 'bs'||(1+g%20), 1+g%5, (ARRAY['ouvert','pourvu','ferme'])[1+g%3], '2026-01-01' FROM generate_series(1,200) g ON CONFLICT DO NOTHING;
INSERT INTO rec_candidats(id,nom,prenom,email,source,cree) SELECT 'rk'||g, 'Candidat '||g, 'Prénom '||(g%50), 'c'||g||'@ex.tn', 'site', now()::text FROM generate_series(1,50000) g ON CONFLICT DO NOTHING;
INSERT INTO rec_candidatures(id,poste_id,candidat_id,etape,note,maj,cree) SELECT 'rc'||g, 'rp'||(1+g%200), 'rk'||(1+g%50000), (ARRAY['nouvelle','preselection','entretien','offre','refus'])[1+g%5], g%20, now()::text, now()::text FROM generate_series(1,80000) g ON CONFLICT DO NOTHING;
INSERT INTO eva_campagnes(id,nom,type,debut,fin,statut,cree) SELECT 'ec'||g, 'Campagne '||g, 'annuelle', (2023+g)||'-01-01', (2023+g)||'-03-31', CASE WHEN g=3 THEN 'ouverte' ELSE 'cloturee' END, now()::text FROM generate_series(1,3) g ON CONFLICT DO NOTHING;
INSERT INTO eva_evaluations(id,campagne_id,mat,evaluateur,statut,note,maj) SELECT 'ev'||g, 'ec'||(1+g%3), (100001 + g % 50000)::text, (100001 + (g % 100))::text, (ARRAY['a_faire','soumise','validee'])[1+g%3], g%5, now()::text FROM generate_series(1,100000) g ON CONFLICT DO NOTHING;
