-- banc : volume réaliste pour les modules (PostgreSQL, matricules du banc 100001..150000)
-- usage : psql … -f outils/banc-modules.sql (base de test uniquement)
BEGIN;
 SELECT 'mv'||g, (100001 + g % 50000)::text, (ARRAY['periodique','embauche','reprise'])[1 + g % 3],
   to_char(date '2024-01-01' + (g % 1000), 'YYYY-MM-DD'), CASE WHEN g % 10 < 8 THEN to_char(date '2024-01-01' + (g % 1000), 'YYYY-MM-DD') END,
   CASE WHEN g % 10 < 8 THEN 'realisee' ELSE 'planifiee' END, CASE WHEN g % 10 < 8 THEN (ARRAY['apte','apte_restrictions','inapte_temporaire'])[1 + g % 3] END,
   to_char(date '2025-01-01' + (g % 1000), 'YYYY-MM-DD'), now()::text, 'banc' FROM generate_series(1,150000) g ON CONFLICT DO NOTHING;
COMMIT;
ANALYZE;
